// Üretilen dosya: tool/ozgun/uret.py. Genel Kültür · Türk kültürü, gelenekler, el sanatları, deyim ve atasözlerinin kökenleri (kolay).
const ozCulture2Kolay = <(String, String, List<String>, String)>[
  ('"Damlaya damlaya göl olur." atasözü hangi düşünceyi öğütler?', 'Küçük birikimler zamanla büyük sonuç verir.', ['Suyu israf etmemek gerekir.', 'Yağmurlu havada dışarı çıkılmamalıdır.', 'Acele eden işini bozar.'], 'Atasözü, azar azar yapılan biriktirmenin sonunda büyük bir varlığa dönüştüğünü anlatır. Tutumluluk ve sabır öğütlenir.'),
  ('"Ağaç yaşken eğilir." atasözüne göre eğitime ne zaman başlanmalıdır?', 'Çocukluk ve gençlik çağında', ['Emeklilikten sonra', 'Evlilikten hemen sonra', 'Askerlik döneminde'], 'Atasözü, insanın küçük yaşta kolayca biçimlendirilebileceğini, alışkanlıkların erken kazanıldığını anlatır.'),
  ('"Sakla samanı, gelir zamanı." atasözü aşağıdaki davranışlardan hangisini destekler?', 'Şimdilik gereksiz görünen bir şeyi ileride kullanmak üzere saklamak', ['Elde olanı hemen tüketip yenisini almak', 'Başkalarına ait eşyaları korumak', 'Hayvanlara kışın samandan başka yem vermek'], 'Bugün değersiz görünen şeylerin bir gün işe yarayabileceğini, bu yüzden atılmaması gerektiğini öğütler.'),
  ('"Üzüm üzüme baka baka kararır." atasözü hangi durumu anlatır?', 'İnsanların bir arada yaşadıkları kişilerden etkilenmesini', ['Meyvelerin olgunlaşmasının uzun sürmesini', 'Bağcılığın sabır gerektiren bir iş olmasını', 'İnsanın yaşlandıkça karamsarlaşmasını'], 'Üzüm tanelerinin yan yana olgunlaşması gibi insanlar da birlikte oldukları kişilerin huylarını edinir.'),
  ('"Bin bilsen de bir bilene danış." atasözünün öğüdü nedir?', 'Ne kadar bilgili olunsa da başkasının görüşü alınmalıdır.', ['Bilgili insanlar az konuşmalıdır.', 'Sayıları ezberlemek yerine anlamak gerekir.', 'Bin kişiden biri gerçekten bilgilidir.'], 'Atasözü, kişinin bilgisine güvenip danışmayı ihmal etmemesini, deneyimli birine akıl sorması gerektiğini anlatır.'),
  ('"Ayağını yorganına göre uzat." atasözü hangi alanda bir öğüt verir?', 'Harcamaları gelire göre ayarlamak', ['Uyurken üşümemek için kalın yorgan almak', 'Yolculukta yük taşımamak', 'Misafire yatak ayırmak'], 'Yorgan kişinin olanaklarını simgeler; atasözü gelirden fazla harcama yapılmamasını öğütler.'),
  ('Gelirinin üstünde harcama yapıp borca giren birine aşağıdaki atasözlerinden hangisi söylenir?', 'Ayağını yorganına göre uzat.', ['Her yokuşun bir inişi vardır.', 'Gülme komşuna, gelir başına.', 'İşleyen demir ışıldar.'], 'Olanaklarına göre yaşamayan birine bu atasözüyle harcamalarını gelirine göre ayarlaması öğütlenir.'),
  ('"İşleyen demir ışıldar." atasözünün anlamı aşağıdakilerden hangisine en yakındır?', 'Çalışan insan gelişir ve parlar.', ['Demirci her zaman kazançlıdır.', 'Pas tutmuş demir kullanılmamalıdır.', 'Sert işler güçlü insanlara verilmelidir.'], 'Kullanılan demir pas tutmaz ve parlar; atasözü çalışmanın insanı canlı, yetenekli ve verimli tuttuğunu anlatır.'),
  ('"Dost acı söyler." atasözüne göre gerçek dostun özelliği nedir?', 'Hoşa gitmese de gerçeği yüzümüze söylemesi', ['Her zaman bizi övmesi', 'Sırlarımızı başkalarına anlatması', 'Zor günlerde uzaklaşması'], 'Gerçek dost, kırıcı da olsa doğruyu söyler; yaltaklanmak yerine dürüst eleştiri yapar.'),
  ('"Gülme komşuna, gelir başına." atasözü hangi davranıştan kaçınmayı öğütler?', 'Başkasının uğradığı kötülükle alay etmekten', ['Komşularla fazla samimi olmaktan', 'Yüksek sesle gülmekten', 'Komşudan ödünç eşya almaktan'], 'Başkasının başına gelen sıkıntıyla eğlenen kişinin aynı sıkıntıyı yaşayabileceği hatırlatılır.'),
  ('"Ne ekersen onu biçersin." atasözünün mesajı nedir?', 'İnsan yaptıklarının karşılığını görür.', ['Tarımda tohum seçimi önemlidir.', 'Hasat zamanı geçirilmemelidir.', 'Her toprak her ürünü vermez.'], 'Tarımdan alınmış bu benzetmeyle iyi ya da kötü her davranışın sonucunun kişinin kendisine döneceği anlatılır.'),
  ('Aşağıdaki atasözlerinden hangisi sabrın önemini anlatır?', 'Sabrın sonu selamettir.', ['Az veren candan, çok veren maldan.', 'Bir musibet bin nasihatten iyidir.', 'Gönül ne kahve ister ne kahvehane.'], '"Sabrın sonu selamettir" sabredenin sonunda kurtuluşa ereceğini anlatır. Diğerleri cömertlik, deneyim ve dostluk temalıdır.'),
  ('"Gönül ne kahve ister ne kahvehane, gönül sohbet ister kahve bahane." sözüne göre kahve içmenin asıl amacı nedir?', 'Dostlarla sohbet edip bir araya gelmek', ['Uykuyu kaçırıp çalışmak', 'Yemek sonrası sindirimi kolaylaştırmak ve dinlenmek', 'Kahvehaneye para kazandırmak'], 'Söz, Türk kültüründe kahvenin bir buluşma ve muhabbet aracı olduğunu, asıl ihtiyacın sohbet olduğunu anlatır.'),
  ('"Bir fincan kahvenin kırk yıl hatırı vardır." sözü Türk kültüründeki hangi değeri yansıtır?', 'Küçük bir iyiliğin bile uzun süre unutulmaması gerektiğini', ['Kahvenin pahalı bir içecek olduğunu', 'Kırk yaşından sonra kahve içilmesi gerektiğini', 'Fincanların kuşaktan kuşağa aktarıldığını'], 'Söz, bir fincan kahve kadar küçük bir ikramın bile vefa ile karşılanmasını, iyiliğin unutulmamasını öğütler.'),
  ('"Görünen köy kılavuz istemez." atasözü hangi durumda söylenir?', 'Apaçık olan bir şey için kanıt ya da açıklama gerekmediğinde', ['Yolculuğa rehbersiz çıkıldığında', 'Köylerin haritada gösterilmediğinde', 'Uzak bir yere giderken yol sorulduğunda'], 'Herkesin açıkça gördüğü bir gerçek için ayrıca açıklama yapmaya ya da yol göstermeye gerek yoktur.'),
  ('"Yuvayı dişi kuş yapar." atasözü aile yaşamında kime önemli bir rol yükler?', 'Kadına', ['Çocuklara', 'Büyükbabaya', 'Komşulara'], 'Atasözü, aile düzeninin kurulup sürdürülmesinde kadının emeğinin ve özeninin belirleyici olduğunu anlatır.'),
  ('"Tatlı dil yılanı deliğinden çıkarır." atasözünün öğüdü nedir?', 'Güzel ve yumuşak konuşma en zor işleri bile çözer.', ['Yılanlarla oynamak tehlikelidir.', 'Tatlı yiyecekler hayvanları çeker.', 'Çok konuşan kişi güven kaybeder.'], 'Kaba söz yerine kibar ve yumuşak bir dil kullanmak, inatçı insanları bile ikna etmeye yeter.'),
  ('"Lafla peynir gemisi yürümez." atasözü kimler için söylenir?', 'Yalnızca konuşup iş yapmayanlar için', ['Gemilerde peynir taşıyan tüccarlar için', 'Az konuşan çalışkan insanlar için', 'Peyniri sevmeyen denizciler için'], 'Bir işin başarılması için söz yetmez, emek gerekir. Sadece konuşarak hiçbir iş yürümez.'),
  ('"Kulağına küpe olmak" deyimi ne anlama gelir?', 'Başına gelen bir olaydan ders çıkarmak', ['Takı takmaya başlamak', 'Herkesin sözünü dinlemek', 'Sık sık kulak ağrısı çekmek'], 'Kişinin yaşadığı ya da duyduğu bir olayın unutulmaz bir ders olması bu deyimle anlatılır.'),
  ('"Etekleri zil çalmak" deyimi hangi duyguyu anlatır?', 'Çok sevinmek', ['Çok korkup telaşlanmak', 'Utanmak', 'Öfkelenmek'], 'Sevinçten yerinde duramamak, çok neşelenmek bu deyimle anlatılır.'),
  ('"Kılı kırk yarmak" deyimi nasıl bir çalışma tarzını anlatır?', 'Bir işte en küçük ayrıntıya kadar aşırı titiz davranmayı', ['İşleri yarım bırakıp başka işe geçmeyi', 'Kırk gün boyunca aynı işle uğraşmayı', 'Saç ve sakal bakımına özen göstermeyi'], 'Kıl gibi ince bir şeyi kırk parçaya ayırmak, aşırı inceleme ve titizliğin abartılı bir anlatımıdır.'),
  ('"Kabak tadı vermek" deyimi hangi durumda kullanılır?', 'Bir şey çok tekrarlandığı için usandırıcı hâle geldiğinde', ['Yemek tuzsuz piştiğinde', 'Bir sebze yeni hasat edildiğinde', 'Bir şaka herkesi güldürdüğünde'], 'Kabak tatsız bir sebze sayılır; çok yinelenen söz ya da davranışın bıkkınlık vermesi bu deyimle anlatılır.'),
  ('"Ağzı süt kokmak" deyimi kimin için söylenir?', 'Çok genç ve deneyimsiz biri için', ['Kahvaltıyı aksatmayan biri için', 'Ağız bakımına özen göstermeyen biri için', 'Hayvancılıkla uğraşan biri için'], 'Deyim, henüz bebeklikten yeni çıkmış gibi toy, tecrübesiz kişileri anlatır.'),
  ('"Sinek avlamak" deyimi özellikle esnaf için hangi durumu anlatır?', 'Dükkânın müşterisiz kalıp işlerin durgun gitmesini', ['Dükkânın böceklere karşı ilaçlanmasını', 'Esnafın erken kapatıp eve gitmesini', 'Satıcının müşteriyle tartışmasını'], 'Yapacak işi olmayan, müşteri bekleyen esnafın boş boş oturması "sinek avlamak" diye anlatılır.'),
  ('"Kendini dev aynasında görmek" deyimi hangi kusuru anlatır?', 'Kendini olduğundan çok daha büyük ve önemli sanmayı', ['Dış görünüşüne fazla zaman ayırmayı', 'Kendi hatalarını sürekli büyütmeyi', 'Başkalarını kendinden üstün görmeyi'], 'Büyüten bir aynaya bakar gibi, kişinin yeteneğini ve değerini abartması bu deyimle anlatılır.'),
  ('Bir şarkıcı, yeni çıkan genç bir sanatçı yüzünden ilgiyi tümüyle kaybediyor. Bu durum için hangi deyim kullanılır?', 'Pabucu dama atılmak', ['Ayağına çabuk olmak', 'Ayakları yere basmak', 'Ayağını denk almak'], 'Pabucu dama atılmak, birinin yerine yenisi geldiği için değerini ve ilgiyi yitirmesidir.'),
  ('"Tası tarağı toplamak" deyimi kökeninde hangi mekânla ilgilidir?', 'Hamamla', ['Mutfakla', 'Pazarla', 'Ahırla'], 'Hamama giden kişi tasını ve tarağını yanında götürürdü. Bunları toplamak oradan ayrılmak demekti; deyim bir yerden göç etmeyi anlatır.'),
  ('"Eski hamam eski tas" deyimi hangi durumu anlatır?', 'Bir değişiklik beklenirken her şeyin yine eskisi gibi kalmasını', ['Eski eşyaların yenilerinden daha sağlam olmasını', 'Hamamların tarihî yapılar olarak korunmasını', 'Yaşlıların gençlere öğüt vermesini'], 'Yaygın anlatıya göre bir hamamın yenilenen tasları kısa sürede eskileriyle değiştirilmiştir. Deyim, değişmesi beklenen bir durumun aynen sürmesini anlatır.'),
  ('Komşusu ip istediğinde "İpe un serdim." diyerek onu geri çeviren kahramanın fıkrasından doğan "ipe un sermek" deyimi ne anlama gelir?', 'Bir isteği yerine getirmemek için bahane uydurmak', ['Bir işi en ince ayrıntısına kadar planlayıp hazırlamak', 'Az bulunan bir malı herkesle bölüşmek', 'Çamaşır kurutmak için bahçeye ip germek'], 'Nasreddin Hoca\'nın bu fıkrasında un ipe serilemeyeceği hâlde bahane olarak öne sürülür. Deyim, işi savsaklamak için mazeret uydurmayı anlatır.'),
  ('"Sürüden ayrılanı kurt kapar." atasözü hangi değeri öne çıkarır?', 'Topluluktan kopmamayı', ['Cesur ve atılgan olmayı', 'Hayvanları sevmeyi', 'Bireysel çalışmayı'], 'Sürüden ayrılan koyunun kurda yem olması gibi, toplumdan ve birlikten ayrılan kişi tehlikeye açık hâle gelir.'),
  ('"Davulun sesi uzaktan hoş gelir." atasözü ne anlatır?', 'Bir şey uzaktan bakınca kolay ve güzel görünür, içine girince öyle olmaz.', ['Davul en çok açık havada çalınmalıdır.', 'Düğünlerde müzik uzaktan da duyulmalıdır.', 'Gürültülü yerlerden uzak durmak gerekir.'], 'Yakından kulak tırmalayan davul uzaktan hoş duyulur; birçok iş ve durum da dışarıdan göründüğü kadar kolay değildir.'),
  ('"Yumurta kapıya gelince" deyimi hangi alışkanlığı eleştirir?', 'Bir işi son ana kadar ertelemeyi', ['Alışverişi her gün yapmayı', 'Konuklara her sabah kahvaltı hazırlamayı', 'Kapıyı kilitlemeyi unutmayı'], 'Deyim, gerekli işin vakit tamamen daralana dek yapılmayıp son anda telaşla ele alınmasını anlatır.'),
  ('Halı ile kilim arasındaki temel teknik fark nedir?', 'Halı düğümlü ve havlıdır, kilim düz dokunur.', ['Halı yalnız ipekten, kilim ise yalnız pamuktan dokunur.', 'Halı tezgâhta, kilim ise her zaman elde örgüyle yapılır.', 'Halıda yalnız kök boya, kilimde ise yalnız sentetik boya kullanılır.'], 'Halıda ipler çözgüye düğümlenir ve yüzeyde hav oluşur; kilim ise atkı ipliklerinin çözgü arasından geçirilmesiyle havsız dokunur.'),
  ('Dokuma tezgâhında uzunlamasına gerilen iplere ne ad verilir?', 'Çözgü', ['Atkı', 'Hav', 'Saçak düğümü'], 'Çözgü iplikleri tezgâhta boylamasına gerilir; atkı iplikleri ise bunların arasından enine geçirilir.'),
  ('Kocaeli\'de kurulan saray fabrikasında dokunan, ince ipek halılarıyla ünlü merkez hangisidir?', 'Hereke', ['Milas', 'Kula', 'Döşemealtı'], 'Hereke\'de 19. yüzyılda kurulan Fabrika-i Hümayun, saray için ipek ve yün halılar üretmiştir; Hereke halısı incelik ve yüksek düğüm sıklığıyla bilinir.'),
  ('Ebrunun "su üzerine resim" olarak anılmasının nedeni nedir?', 'Desenin kıvamlı su yüzeyinde oluşturulup kâğıda aktarılması', ['Desenin suluboyayla doğrudan kâğıda çizilmesi', 'Kâğıdın önce suya batırılıp sonra boyanması', 'Boyanın ıslak duvar sıvasına uygulanması'], 'Ebru ustası deseni teknedeki kitreli suyun üzerinde oluşturur; kâğıt yüzeye bırakılınca desen kâğıda geçer.'),
  ('Geleneksel hat sanatında hattatın kullandığı yazı aracı nedir?', 'Kamış kalem', ['Çelik uçlu dolma kalem', 'Kaz tüyünden yapılmış kalem', 'Kurşun ve kömür karışımı kalem'], 'Hattatlar kamıştan yontulan kalemlerle yazar; kalemin ucu yazı türüne göre farklı genişlikte açılır.'),
  ('Köşeli, geometrik harfleriyle tanınan ve en eski İslam yazılarından biri olan yazı türü hangisidir?', 'Kûfi', ['Talik', 'Rika', 'Divani'], 'Kûfi yazı, adını Irak\'taki Kûfe kentinden alır. Düz çizgili, köşeli yapısıyla mimari süslemelerde de kullanılmıştır.'),
  ('Osmanlı padişahlarının resmî belgelerin başına konulan, adlarını ve unvanlarını içeren özel imzası hangisidir?', 'Tuğra', ['Hilye', 'Kitabe', 'Mühür yüzüğü'], 'Tuğra, padişahın adını, babasının adını ve "el-muzaffer daima" gibi ifadeleri barındıran stilize bir imzadır.'),
  ('Osmanlı çiniciliğinin altın çağı sayılan 16. yüzyılda en ünlü çini üretim merkezi hangisidir?', 'İznik', ['Avanos', 'Menemen', 'Çanakkale'], 'İznik atölyeleri 16. yüzyılda saray ve camiler için çok kaliteli çiniler üretmiştir. Kütahya özellikle 18. yüzyıldan sonra öne çıkmıştır.'),
  ('"Çini" sözcüğünün kökeni hangi ülke adına dayanır?', 'Çin', ['Japonya', 'Hindistan', 'İran'], 'Sözcük, porselen ve seramikleriyle ünlü Çin\'den gelir. Türkçede zamanla sırlı süsleme karolarının genel adı olmuştur.'),
  ('Kızılırmak\'ın getirdiği kille yapılan çömlekleriyle ünlü, Kapadokya\'daki ilçe hangisidir?', 'Avanos', ['Ürgüp', 'Göreme', 'Hacıbektaş'], 'Avanos\'ta Kızılırmak\'ın kırmızı kiliyle çömlekçilik binlerce yıldır sürer. Çömlekçi çarkı ayakla döndürülür.'),
  ('Çok ince gümüş ya da altın tellerin bükülüp kıvrılarak dantel gibi işlenmesiyle yapılan takı sanatına ne denir?', 'Telkari', ['Tombak işçiliği', 'Kakma', 'Tezhip'], 'Telkari, tellerin lehimlenerek birleştirilmesiyle oluşan ince işçiliktir. Midyat ve Beypazarı bu sanatın tanınmış merkezlerindendir.'),
  ('Ahşap yüzeye oyulan yuvalara deniz kabuğundan kesilmiş parlak parçaların yerleştirildiği süsleme sanatı hangisidir?', 'Sedef kakma', ['Kündekari tekniği', 'Telkari', 'Ebru'], 'Sedef, bazı deniz kabuklarının iç yüzeyindeki parlak tabakadır. Kakmacılar onu keserek ahşap, kaplumbağa kabuğu ya da fildişi üzerine yerleştirir.'),
  ('Anadolu\'da başörtülerinin kenarlarına dikiş iğnesi ve iplikle düğümler atılarak yapılan ince süslemeye ne ad verilir?', 'İğne oyası', ['Tığ işi dantel', 'Mekik örgüsü', 'Kanaviçe nakışı'], 'İğne oyası, yalnız iğne ve iplikle, ilmeklerin üst üste düğümlenmesiyle oluşturulur. Tığ ve mekik oyaları ise farklı araçlarla yapılır.'),
  ('Pamuktan dokunan, sıcak havada serinlik veren ve adını İstanbul\'un bir ilçesinden alan geleneksel kumaş hangisidir?', 'Şile bezi', ['Buldan bezi', 'Rize bezi', 'Kutnu'], 'Şile bezi, kendine özgü kırışık dokusu sayesinde tene yapışmaz ve yaz giysileri için tercih edilir.'),
  ('Eskişehir\'de çıkarılan, hafif ve kolay işlenebilen, özellikle pipo yapımında kullanılan beyaz mineral hangisidir?', 'Lületaşı', ['Oltu taşı', 'Sünger taşı', 'Su mermeri'], 'Lületaşı (sepiyolit), dünyada en kaliteli örnekleriyle Eskişehir\'de çıkarılır. Yabancı dillerde "deniz köpüğü" adıyla da anılır.'),
  ('Erzurum\'un bir ilçesinin adını taşıyan, tespih ve takı yapımında kullanılan siyah süs taşı hangisidir?', 'Oltu taşı', ['Lületaşı ya da sepiyolit', 'Obsidyen', 'Kehribar'], 'Oltu taşı fosilleşmiş bitki kalıntılarından oluşan siyah, parlak bir taştır. Ocaktan ilk çıktığında yumuşaktır, zamanla sertleşir.'),
  ('Köylülerin eskiden işlenmemiş deriden yaptığı, iplerle bağlanan basit ayakkabıya ne denir?', 'Çarık', ['Mest', 'Yemeni', 'Terlik'], 'Çarık, sığır derisinden kesilip kenarları iple büzülerek ayağa bağlanan dayanıklı bir ayakkabıdır.'),
  ('Geleneksel giyimde belin bir ya da birkaç kez sarılmasıyla bağlanan uzun kumaş şeride ne denir?', 'Kuşak', ['Yaka', 'Yelek ya da cepken', 'Çevre'], 'Kuşak, hem giysiyi bele tutturmaya hem de bele para kesesi, mendil gibi eşyaları sıkıştırmaya yarardı.'),
  ('Kız isteme geleneğinde gelin adayının, damat adayının kahvesine bazen şeker yerine tuz koyması geleneksel olarak nasıl yorumlanır?', 'Damadın sabrını ve hoşgörüsünü sınayan şakacı bir adet', ['Ailenin evliliği kesin olarak reddettiğinin bir işareti', 'Gelin adayının yemek yapmayı bilmediğinin itirafı', 'Kahvenin bozulduğunu gösteren tesadüfi bir olay'], 'Tuzlu kahveyi yüzünü buruşturmadan içen damat adayının sabırlı ve anlayışlı olduğu düşünülür. Bu adet bir ret değil, şakacı bir sınamadır.'),
  ('Kızın evlenirken yeni evine götürmek üzere yıllarca hazırladığı ev eşyası, giysi ve el işlerinin bütününe ne ad verilir?', 'Çeyiz', ['Okuntu', 'Kalın', 'Nevale'], 'Çeyiz sandığında oya, dantel, örtü gibi el emekleri bulunur. Bazı yörelerde düğünden önce çeyiz sergilenir.'),
  ('Geleneksel Türk toplumunda doğumdan sonra annenin ve bebeğin özellikle dikkat edilerek korunduğu süre genellikle kaç gündür?', '40', ['7', '15', '100'], 'Lohusalık ve "kırklama" geleneği kırk güne dayanır. Bu sürenin sonunda bebek kırk suyu ile yıkanır ve "kırkı çıktı" denir.'),
  ('Bebeğin ilk dişi çıktığında kaynatılmış buğdayla düzenlenen kutlamaya ne ad verilir?', 'Diş buğdayı', ['Kırk hamamı töreni', 'Beşik toyu', 'Sünnet aşı'], 'Diş buğdayı ya da diş hediği kutlamasında bebeğin önüne çeşitli nesneler konur. Bebeğin hangisini seçtiği, ilerideki mesleğine yorulur.'),
  ('Diş buğdayı kutlamasında bebek önüne konan nesneler arasından makası seçiyor. Geleneğe göre bu seçim nasıl yorumlanır?', 'Terzi olacağına', ['Öğretmen olacağına', 'Asker olacağına', 'Din adamı olacağına'], 'Bu kutlamada her nesne bir mesleği simgeler; makas terziliğe, kalem okumaya, kitap öğretmenlik ya da din adamlığına yorulur.'),
  ('Anadolu\'da bir yakını ölen evde birkaç gün yemek pişirilmez. Bu sırada komşuların davranışı geleneksel olarak nasıldır?', 'Cenaze evine yemek götürüp yaslı aileyi doyururlar.', ['Evin önüne kara bir bayrak asıp uzak dururlar.', 'Yaslı aileyi kendi evlerinde misafir ederek ağırlarlar.', 'Ölenin eşyalarını toplayıp yoksullara dağıtırlar.'], 'Yas tutan aile yemek hazırlamakla uğraşmasın diye komşular ve akrabalar sırayla yemek getirir. Bu, dayanışmanın en belirgin örneklerinden biridir.'),
  ('Anadolu\'da ölümün ardından kavrulup dağıtılan, ölenin ruhu için hayır olarak görülen tatlı hangisidir?', 'Helva', ['Baklava', 'Aşure', 'Revani'], 'İrmik ya da un helvası kavrulup komşulara ve taziyeye gelenlere dağıtılır; bu, ölen kişi için hayır duası istemek anlamı taşır.'),
  ('Ergenekon\'dan çıkışın kutlandığı ve aynı zamanda baharın gelişini simgeleyen bayram hangisidir?', 'Nevruz', ['Hıdırellez', 'Saya', 'Koç katımı'], 'Nevruz 21 Mart\'ta kutlanır. Türk geleneğinde Ergenekon\'dan çıkış ve demir dövme törenleriyle de ilişkilendirilir.'),
  ('Hızır ile İlyas\'ın yeryüzünde buluştuğuna inanılan ve 6 Mayıs\'ta kutlanan bahar bayramı hangisidir?', 'Hıdırellez', ['Nevruz', 'Saya', 'Kırklar ya da Saya'], 'Hıdırellez adı Hızır ve İlyas adlarının birleşiminden türemiştir. Bu günde doğanın uyandığına ve bereket geldiğine inanılır.'),
  ('Türk hamamında en sıcak bölüm olan ve ortasında göbek taşı bulunan kısma ne ad verilir?', 'Sıcaklık', ['Soğukluk ya da camekân', 'Ilıklık', 'Külhan'], 'Hamamlar soğukluk (soyunma), ılıklık ve sıcaklık bölümlerinden oluşur. Sıcaklığın ortasındaki göbek taşı alttan ısıtılır.'),
  ('Erkekler hamamında müşterileri keseleyip yıkayan görevliye ne denir?', 'Tellak', ['Natır', 'Külhancı', 'Kahveci'], 'Erkek hamamlarında bu işi tellak, kadın hamamlarında ise natır yapar.'),
  ('Hamamda vücudu sarmak için kullanılan, genellikle ipek ya da pamuktan dokunmuş çizgili örtüye ne ad verilir?', 'Peştamal', ['Kese', 'Nalın', 'Yaşmak ya da ferace'], 'Peştamal, hamamda bele sarılan geleneksel örtüdür. Kese ise ölü deriyi temizlemek için kullanılan kaba kumaş eldivendir.'),
  ('Hamamda ıslak ve kaygan zeminde yürümek için giyilen, tahtadan yapılmış yüksek tabanlı terliğe ne denir?', 'Nalın', ['Mest', 'Çarık', 'Yemeni'], 'Nalınlar tahta tabanları sayesinde ayağı sıcak zeminden ve sudan korur. Bazı nalınlar sedefle süslenirdi.'),
  ('Karagöz oyununda Hacivat ile Karagöz\'ün kişilik özellikleri karşılaştırıldığında hangisi doğrudur?', 'Hacivat kurallara uyan, kibar ve okumuş; Karagöz saf, açık sözlü ve halktan biridir.', ['Hacivat cahil ve kaba; Karagöz bilgili ve süslü konuşan biridir.', 'İkisi de aynı eğitimi almış, aynı biçimde konuşan saray adamlarıdır.', 'Hacivat yalnızca şarkı söyler, Karagöz ise hiç konuşmaz.'], 'İki karakter birbirinin karşıtıdır: Hacivat medrese görmüş, çıkarcı ve kurallara bağlı; Karagöz ise içten, cahil ama zeki bir halk adamıdır.'),
  ('Orta oyununun bu adı almasının nedeni nedir?', 'Seyircilerin çevrelediği alanın ortasında oynanması', ['Oyunun gecenin ortasında başlaması', 'Oyunun orta sınıfa hitap etmesi', 'Oyunun iki perdenin ortasında oynanması'], 'Orta oyunu, "meydan" ya da "palanga" denen açık alanda, çevresini seyircilerin sardığı bir meydanın ortasında sergilenir.'),
  ('Âşığın sanat hayatında kullandığı ve genellikle ustası tarafından verilen takma ada ne denir?', 'Mahlas', ['Lakap', 'Unvan', 'İcazet adı'], 'Mahlas, âşık şiirinde tapşırmada kullanılır. Ustalar çoğu zaman çırağın kişiliğine uygun bir mahlas verirdi.'),
  ('Kör olmasına karşın sazı ve sözüyle Anadolu\'yu dolaşan, "Uzun ince bir yoldayım" dizeleriyle tanınan âşık kimdir?', 'Âşık Veysel', ['Karacaoğlan', 'Pir Sultan Abdal', 'Dadaloğlu'], 'Sivas\'ın Şarkışla ilçesinde doğan Âşık Veysel, 20. yüzyıl âşık edebiyatının en tanınmış temsilcilerindendir.'),
  ('Ölen bir kişinin ardından onun iyiliklerini ve duyulan acıyı dile getiren halk şiiri türüne ne ad verilir?', 'Ağıt', ['Koçaklama', 'Güzelleme', 'Taşlama'], 'Ağıt, ölüm acısını anlatır. Koçaklama yiğitliği, güzelleme sevgiliyi ve doğayı, taşlama ise eleştiriyi işler.'),
  ('Masalların başında anlatıcının dinleyicinin dikkatini çekmek için söylediği "Evvel zaman içinde, kalbur saman içinde" türünden kalıp sözlere ne ad verilir?', 'Tekerleme', ['Bilmece ya da muamma', 'Ninni', 'Ağıt'], 'Tekerleme, uyaklı ve çoğu zaman mantık dışı söz dizileridir. Masalın gerçek dünyadan ayrı bir dünyada geçtiğini sezdirir.'),
  ('Bir şeyin adı söylenmeden özellikleri benzetmelerle anlatılıp dinleyiciden bulunmasının istendiği halk edebiyatı türü hangisidir?', 'Bilmece', ['Tekerleme', 'Mani', 'Destan'], 'Bilmece zekâyı ve hayal gücünü geliştirir; nesneler doğrudan adlandırılmaz, benzetmeler ve ipuçlarıyla sezdirilir.'),
  ('Ninnilerin geleneksel kültürdeki temel işlevi hangisidir?', 'Çocuğu uyuturken annenin duygu ve dileklerini dile getirmek', ['Kahramanlıkları ve savaşları anlatıp gençleri cesaretlendirmek', 'Ölenin ardından duyulan acıyı topluca paylaşmak', 'Kötü yöneticileri iğneleyici bir dille eleştirmek'], 'Ninniler çocuğu uyutmak için ezgiyle söylenir; anne bu sözlerde özlem, dert ve çocuğuna dair umutlarını da anlatır.'),
  ('Nasreddin Hoca\'nın türbesinin bulunduğu ve her yıl adına şenlik düzenlenen ilçe hangisidir?', 'Akşehir', ['Sivrihisar', 'Beypazarı', 'Kula'], 'Nasreddin Hoca\'nın Sivrihisar\'ın Hortu köyünde doğduğu, Akşehir\'de yaşayıp orada öldüğü kabul edilir. Akşehir\'deki türbesi ünlüdür.'),
  ('Bir öğrenci, kazanma olasılığı çok düşük bir yarışmaya yine de başvuruyor. Arkadaşları güldüğünde onun söyleyebileceği, Nasreddin Hoca\'dan kalma söz hangisidir?', 'Ya tutarsa!', ['Parayı veren düdüğü çalar.', 'Ye kürküm ye.', 'Yorgan gitti, kavga bitti.'], 'Göle maya çalan Hoca\'nın "Ya tutarsa!" sözü, düşük bir olasılığa umut bağlayarak denemeyi anlatır.'),
  ('Karadeniz yöresine özgü, kemençe eşliğinde hızlı ve titrek hareketlerle oynanan halk oyunu hangisidir?', 'Horon', ['Zeybek ve efe oyunları', 'Kaşık oyunları ve karşılama', 'Bar ve halay oyunları'], 'Horon, Doğu Karadeniz\'in en tanınmış oyunudur. Oyuncular omuz omuza ya da el ele dizilir, kemençenin hızlı ezgisiyle titreyerek oynar.'),
  ('Ege yöresinde ağır ve gösterişli hareketlerle oynanan, efe kültürüyle özdeşleşmiş halk oyunu hangisidir?', 'Zeybek', ['Horon ve kemençe havası', 'Bar ve tamzara', 'Hora ve karşılama'], 'Zeybek, Ege efelerinin yiğitliğini ve onurunu yansıtır. Ağır tempoyla, dizlerin yere vurulduğu gösterişli figürlerle oynanır.'),
  ('Halay oyununda en başta durup elinde mendil sallayarak oyunu yöneten kişiye ne ad verilir?', 'Halaybaşı', ['Pişekâr ya da meydan yöneticisi', 'Cazgır ya da çağırıcı', 'Yedek oyuncu ya da poççik'], 'Halaybaşı figürleri değiştirir ve diğer oyunculara yön verir. Elindeki mendil hem süs hem de işaret aracıdır.'),
  ('Ellerde tahta kaşıkların birbirine vurularak ritim tutulduğu, özellikle Konya ve Silifke yöresinde oynanan oyunlar hangisidir?', 'Kaşık oyunları', ['Teke oyunları ve zortlatmalar', 'Bar oyunları ve kafkaslar', 'Zeybek oyunları ve efe havaları'], 'Kaşık oyunlarında oyuncular iki elinde tuttuğu kaşıkları şakırdatarak müziğe eşlik eder.'),
  ('Mevlevi müziğinin simgesi olan, kamıştan yapılmış ve üflenerek çalınan çalgı hangisidir?', 'Ney', ['Zurna ya da mey', 'Kaval ya da çığırtma', 'Klarnet ya da gırnata'], 'Ney kamıştan yapılır ve dokuz boğumludur. Mevlana\'nın Mesnevi\'si "Dinle, bu ney nasıl şikâyet ediyor" anlamındaki dizelerle başlar.'),
  ('Osmanlı ordusunun savaşta ve törenlerde moral vermek için çalan askerî müzik topluluğuna ne ad verilir?', 'Mehter', ['Enderun korosu', 'Yeniçeri ocağı', 'Mevlevihane heyeti'], 'Mehter dünyanın en eski askerî bandolarından biri kabul edilir. Kös, zurna, nakkare, zil ve boru gibi çalgılar kullanılır.'),
  ('Edirne\'de yüzyıllardır düzenlenen ve en eski sürekli spor organizasyonlarından biri sayılan güreş şenliği hangisidir?', 'Kırkpınar', ['Cirit şöleni ve at oyunları', 'Deve güreşi festivali', 'Kafkas karakucak şenliği'], 'Kırkpınar Yağlı Güreşleri 14. yüzyıldan beri düzenlendiği kabul edilen bir şenliktir. UNESCO listesine 2010\'da alınmıştır.'),
  ('Güreşten dilimize geçen "sırtı yere gelmemek" deyimi bugün hangi anlamda kullanılır?', 'Hiç yenilmemek', ['Yere uzanıp dinlenmemek', 'Sırt ağrısı çekmemek', 'Uzun süre ayakta kalmak'], 'Güreşte sırtı yere gelen pehlivan yenilmiş sayılır. Deyim, kimseye yenilmeyen, her zaman üstün gelen kişiler için kullanılır.'),
  ('13. yüzyılda Anadolu\'da esnaf ve zanaatkârları bir çatı altında toplayan Ahilik teşkilatının kurucusu sayılan kişi kimdir?', 'Ahi Evran', ['Hacı Bayram-ı Veli', 'Şeyh Edebali', 'Yunus Emre'], 'Ahi Evran, Kırşehir merkezli olarak esnafı meslek ve ahlak kurallarıyla örgütlemiştir. Ahilik hem bir meslek örgütü hem de bir ahlak okuludur.'),
  ('Ahilik geleneğine göre bir mesleği öğrenen kişinin geçtiği basamaklar sırasıyla hangisidir?', 'Çırak, kalfa, usta', ['Kalfa, çırak, sonra usta', 'Usta, kalfa, çırak', 'Çırak, usta, kalfa'], 'Mesleğe çırak olarak başlanır, beceri kazanınca kalfa olunur; yeterliliği onaylanan kalfa da usta olup kendi dükkânını açabilir.'),
  ('Osmanlı\'da zenginlerin para bıraktığı, yoksulların da yalnız ihtiyacı kadarını aldığı, cami avlularındaki oyuklu taşlara ne ad verilir?', 'Sadaka taşı', ['Musalla taşı', 'Binek taşı', 'Nişan taşı'], 'Sadaka taşında veren de alan da birbirini görmezdi. Böylece yardım alanın onuru korunur, verenin de gösterişe kaçması önlenirdi.'),
  ('Geleneksel bir evde konuğa odadaki en itibarlı yerin, yani başköşenin gösterilmesi neyi ifade eder?', 'Konuğa duyulan saygıyı', ['Konuğun evden kısa sürede ayrılması isteğini', 'Konuğun ev işlerine yardım etmesi beklentisini', 'Konuğun yaşının ev sahibinden küçük olduğunu'], 'Başköşe odanın kapıdan en uzak ve en rahat yeridir. Bu yerin konuğa ayrılması onun onurlandırıldığını gösterir.'),
  ('Geleneksel bir aile sofrasında yere düşen bir ekmek parçası görülünce yaygın olarak ne yapılır?', 'Alınıp öpülür ve ayak basılmayacak bir yere konur.', ['Hemen çöpe atılıp yenisi getirilir.', 'Sofradan kalkan son kişiye verilir.', 'Sofra örtüsünün altına gizlenir.'], 'Ekmek Türk kültüründe nimetin simgesidir ve kutsal sayılır. Düşen ekmek öpülüp alnına konarak yüksekçe bir yere bırakılır.'),
  ('Bir konuk, yemek sonrası ev sahibine "Elinize sağlık." diyor. Ev sahibinin geleneksel yanıtı hangisi olur?', 'Afiyet olsun.', ['Güle güle kullanın.', 'Geçmiş olsun.', 'Hayırlı işler.'], '"Elinize sağlık" yemeği hazırlayanın emeğine teşekkürdür; ev sahibi de konuğa yemeğin ona yarar sağlamasını dileyerek "Afiyet olsun" der.'),
  ('Halk inanışına göre mavi nazar boncuğunun çatlaması ya da kırılması nasıl yorumlanır?', 'Kötü bir bakışı üzerine çekip sahibini koruduğu', ['Boncuğun sahibine yakında bir müjde ve kısmet geleceği', 'Evde bir misafirin ağırlanacağı', 'Boncuğun eskidiği ve uğurunun bittiği'], 'İnanışa göre nazar boncuğu, kıskanç ve kötü bakışın gücünü kendine çeker; çatlaması bu bakışın sahibine ulaşmadan engellendiği biçiminde yorumlanır.'),
  ('Kutsal sayılan yerlerdeki ağaçların dallarına bez parçaları bağlanması geleneğinin amacı nedir?', 'Bir dileğin gerçekleşmesini istemek', ['Ağacın meyvelerini kuşlardan korumak', 'Yolu kaybedenlere iz bırakmak', 'Ağacı hastalıktan korumak'], 'Çaput bağlama, Anadolu\'da yaygın bir dilek uygulamasıdır. Bağlanan bez, dileği ağaca emanet etmeyi simgeler.'),
  ('Konuşma sırasında olumsuz bir olasılıktan söz eden birinin hemen "Tahtaya vurayım." demesi hangi inanca dayanır?', 'Söylenen kötü şeyin gerçekleşmesini önlemek', ['Konuşmanın sona erdiğini belirtmek', 'Dinleyicilerin dikkatini çekmek', 'Söylenen sözün doğruluğuna yemin etmek'], 'Tahtaya vurmak, kötü bir söz söylendikten sonra o kötülüğün başa gelmesini engellemek amacıyla yapılan yaygın bir uğur davranışıdır.'),
  ('Birinin kulağı çınladığında söylenen "Biri beni anıyor." sözü hangi halk inanışını yansıtır?', 'Uzakta biri adımızı andığında kulağımızın çınladığı', ['Kulak çınlamasının yakında yağmur yağacağını gösterdiği', 'Kulak çınlamasının bir hastalığın başlangıcı olduğu', 'Kulağı çınlayan kişinin yalan söylediği'], 'Halk arasında kulak çınlaması, o anda birinin kişiyi düşünüp andığı biçiminde yorumlanır.'),
  ('Bayram sabahı gençlerin aile büyüklerinin elini öpüp alnına koymasının taşıdığı anlam nedir?', 'Büyüklere saygı ve onların duasını alma isteği', ['Büyüklerin bayram harçlığını hemen istemek', 'Bayramın resmî olarak başladığını ilan etmek', 'Bir anlaşmazlığın sona erdiğini noterden onaylamak'], 'El öpme, Türk kültüründe saygının en belirgin göstergelerindendir. Büyük de karşılığında dua eder ve çocuklara harçlık ya da şeker verir.'),
  ('Geleneksel Türk evlerinde üst katın sokağa doğru taşan çıkıntılı bölümüne ne denir?', 'Cumba', ['Avlu', 'Sofa', 'Ocaklık'], 'Cumba, odanın sokağı daha geniş görmesini sağlar ve dar sokaklarda üst katlara alan kazandırır.'),
  ('Göçebe Yörüklerin yazın serin dağlara, kışın ılık ovalara göç etmesi hangi yaşam düzenine dayanır?', 'Yaylak ve kışlak düzenine', ['Kentlerde yerleşik ticarete', 'Sulu tarım ve bağcılığa', 'Madencilik ve taş ocağı işletmeciliğine'], 'Hayvanlarını otlatmak için yazın yaylaya, kışın da kışlağa göç eden Yörükler, mevsime göre otlağı izleyen bir hayvancılık düzeni sürdürür.'),
  ('Omuza ya da hayvan sırtına atılarak kullanılan, iki gözlü dokuma torbaya ne ad verilir?', 'Heybe', ['Çuval ya da harar', 'Torba ya da dağarcık', 'Sandık ya da çekmece'], 'Heybe genellikle kilim tekniğiyle dokunur. İki gözü yükü dengeli taşımayı sağlar; göçebelerin ve köylülerin yol eşyasıdır.'),
  ('Ramazan\'da sahura kaldırmak için mahalle mahalle dolaşan ve mani söyleyen kişinin elindeki çalgı hangisidir?', 'Davul', ['Zurna ya da sipsi', 'Bağlama ya da cura', 'Kemençe ya da rebap'], 'Ramazan davulcusu sahur vakti sokakları dolaşıp mani söyleyerek halkı uyandırır. Bayramda da kapı kapı dolaşıp bahşiş alır.'),
  ('Ramazan ayına özgü, ince nişasta yapraklarının şekerli süte batırılıp gül suyuyla tatlandırıldığı tatlı hangisidir?', 'Güllaç', ['Kadayıf ya da künefe', 'Sütlaç ya da muhallebi', 'Revani ya da şekerpare'], 'Güllaç yaprakları sütle yumuşatılır, araları cevizle doldurulur. Hafif yapısı nedeniyle iftarlarda tercih edilen geleneksel bir tatlıdır.'),
  ('Osmanlı\'da 1718-1730 yılları arasına adını veren ve bu dönemde soylulardan halka kadar tutkuyla yetiştirilen çiçek hangisidir?', 'Lale', ['Sümbül', 'Gül', 'Karanfil'], 'Lale Devri, III. Ahmet ve Sadrazam Nevşehirli İbrahim Paşa dönemidir. Bu dönemde lale soğanları çok yüksek fiyatlara alınıp satılmıştır.'),
  ('Şebeke suyu yokken kentlerde deri kırbalarla evlere ve çarşılara su taşıyan kişiye ne ad verilirdi?', 'Saka', ['Tellal ya da münadi', 'Pazvant ya da bekçi', 'Arzuhalci ya da kâtip'], 'Sakalar suyu çeşmelerden alıp sırtlarında ya da at üzerinde taşırdı. Osmanlı\'da sakaların da bir loncası vardı.'),
  ('Okuma yazma bilmeyenler için resmî dairelere verilecek dilekçeleri ücret karşılığında yazan kişiye ne denirdi?', 'Arzuhalci', ['Saka ya da sucu', 'Hallaç ya da yorgancı', 'Tellal ya da çığırtkan'], 'Arzuhal "dilek, istek" anlamına gelir. Arzuhalciler genellikle adliye ve hükümet konaklarının önünde küçük masalarıyla çalışırdı.'),
  ('Kış akşamlarında sokaklarda uzun bir çağrıyla dolaşıp darıdan yapılmış ekşimsi bir içecek satan seyyar satıcı hangisidir?', 'Bozacı', ['Salepçi', 'Şerbetçi', 'Sucu'], 'Bozacılar akşamları "Booozaa!" diye seslenerek mahallelerde dolaşırdı. Boza genellikle üzerine tarçın ve leblebi serpilerek içilir.'),
  ('Bıçak, makas ve satır gibi kesici aletleri taşınabilir bir çarkla bileyen seyyar zanaatkâra ne denir?', 'Bileyici', ['Kalaycı ya da lehimci', 'Lehimci', 'Hurdacı'], 'Bileyiciler sırtlarında ya da tekerlekli düzeneklerde taşıdıkları bileği taşıyla mahallelerde dolaşır, körelmiş aletleri keskinleştirirdi.'),
  ('Yolculuk eden kervanların konakladığı, hem hanın hem de güvenli bir konaklamanın sağlandığı Selçuklu yapısına ne ad verilir?', 'Kervansaray', ['Bedesten ya da arasta', 'Arasta', 'İmaret'], 'Kervansaraylar, ticaret yolları boyunca belirli aralıklarla kurulur ve yolculara ile hayvanlarına bakım sağlardı.'),
  ('Tatil için ayrıntılı bir bütçe hazırlayan bir aile, gittikleri yerde fiyatların beklediklerinden çok yüksek olduğunu görüyor. Bu durumu en iyi anlatan atasözü hangisidir?', 'Evdeki hesap çarşıya uymaz.', ['Damlaya damlaya göl olur, sakla samanı gelir zamanı.', 'Ağaç yaşken eğilir, sonradan eğilmez.', 'Ne ekersen onu biçersin, iyilik eden iyilik bulur.'], 'Önceden yapılan plan ve hesaplar, gerçek koşullarla karşılaşınca çoğu zaman tutmaz.'),
  ('Dürüst olmayan bir satıcının yalanları birkaç gün içinde ortaya çıkıyor. Bu durumu anlatan atasözü hangisidir?', 'Yalancının mumu yatsıya kadar yanar.', ['Sütten ağzı yanan yoğurdu üfleyerek yer.', 'Söz gümüşse sükût altındır, az konuşmalıdır.', 'Kervan yolda düzülür, eksik zamanla tamamlanır.'], 'Yalan uzun süre gizlenemez; tıpkı akşam yakılan mumun yatsı vaktine kadar tükenmesi gibi kısa sürede ortaya çıkar.'),
  ('"Dağ dağa kavuşmaz, insan insana kavuşur." atasözü hangi durumda söylenir?', 'Uzun süre görüşmeyen tanıdıkların beklenmedik bir yerde karşılaşmasında', ['Dağlık bir bölgede yolculuğa çıkılırken', 'İki köy arasında yol yapımı tartışılırken', 'Doğal afetler hakkında konuşulurken'], 'Dağlar yerinden oynamaz ama insanlar yer değiştirir; birbirinden ayrılanlar bir gün yeniden karşılaşabilir.'),
  ('Kahvehanede konuşulanları çevresine abartarak anlatan, küçük bir olayı büyük bir sorun gibi gösteren biri için hangi deyim kullanılır?', 'Pireyi deve yapmak', ['Eteğindeki taşları dökmek', 'Ağzı kulaklarına varmak', 'Su koyuvermek'], 'Pire çok küçük, deve çok büyük bir canlıdır; deyim önemsiz bir şeyi aşırı büyütmeyi anlatır.'),
  ('Öğretmen soruyu sorar sormaz soruyu bitirmesini beklemeden doğru yanıtı veren öğrenci için hangi deyim kullanılabilir?', 'Leb demeden leblebiyi anlamak', ['Ağzında bakla ıslanmamak', 'Kulak asmamak', 'Dut yemiş bülbül gibi susup kalmak'], 'Bu deyim, söylenecek şeyi daha sözün başında sezecek kadar anlayışlı ve zeki olmayı anlatır.'),
  ('Muharrem ayında buğday, kuru baklagiller ve kuru meyvelerle pişirilip komşulara dağıtılan tatlı hangisidir?', 'Aşure', ['Güllaç', 'Helva', 'Zerde'], 'Halk anlatısına göre aşure, Nuh\'un gemisindekilerin tufandan sonra ellerinde kalan yiyecekleri birleştirerek pişirdiği yemeği anar.'),
  ('Aşure pişirildikten sonra komşulara dağıtılması geleneği hangi değeri öne çıkarır?', 'Paylaşma ve komşuluk ilişkilerini güçlendirme', ['Yemeğin hızla bozulmasını önleme', 'Mutfakta yer açma', 'Pişirenin ustalığını kanıtlama'], 'Aşurenin çok miktarda pişirilip komşu kapılarına götürülmesi, bolluğun paylaşılması ve dayanışma anlamı taşır.'),
  ('Köylerde erişte kesme, bulgur kaynatma ya da ev yapımı gibi işlerin komşular tarafından karşılıksız ve topluca yapılmasına ne ad verilir?', 'İmece', ['Ahilik', 'Lonca', 'Vakıf'], 'İmecede herkes sırayla birbirinin işine yardım eder. Böylece ağır işler kısa sürede ve eğlenceli bir ortamda biter.'),
  ('Yaz sonunda yapılan salça, tarhana ve erişte hazırlıklarına topluca "kışlık" denmesinin nedeni nedir?', 'Bu yiyeceklerin kış boyunca tüketilmek üzere saklanması', ['Bu yiyeceklerin yalnız kış mevsiminde ve kar yağarken yapılabilmesi', 'Bu ürünlerin soğuk havada daha çabuk pişmesi', 'Bu işlerin yalnız kış tatilinde yapılması'], 'Taze ürünün bol olduğu yaz sonunda yiyecekler kurutulup saklanır; böylece taze ürünün bulunmadığı kış aylarına hazırlanılır.'),
  ('Kandil gecelerinde fırınlarda yapılıp komşulara ve yakınlara dağıtılan, üzeri susamlı halka biçimli çörek hangisidir?', 'Kandil simidi', ['Ramazan pidesi', 'Paskalya çöreği', 'Gevrek'], 'Kandil simidi kandil gecelerine özgüdür. Bu gecelerde simitlerin paylaşılması, gecenin bereketini çevreyle bölüşmek anlamına gelir.'),
  ('Sınavdan yüksek not aldığını öğrenen bir öğrencinin sevinçten yüzünün güldüğünü anlatan deyim hangisidir?', 'Ağzı kulaklarına varmak', ['Burnunun dikine gitmek ve söz dinlememek', 'Gözden düşüp itibarını kaybetmek', 'Kulak asmamak ve önemsememek'], 'Bu deyim, insanın çok sevindiği için geniş geniş gülmesini anlatır.'),
  ('Annesinin uyarılarına rağmen bildiğini yapmaya devam eden bir çocuk için hangi deyim kullanılır?', 'Burnunun dikine gitmek', ['Ağzı kulaklarına varıp sevinmek', 'Eli kulağında olup yaklaşmak', 'Gözü tok olup açgözlü olmamak'], 'Burnunun dikine gitmek, kimseyi dinlemeden yalnız kendi bildiğini yapmaktır.'),
  ('"Eli kulağında" sözü bir olay için kullanıldığında ne anlatır?', 'Olayın gerçekleşmesinin çok yakın olduğunu', ['Olayın çok uzun zaman önce yaşanıp unutulduğunu', 'Olayın kimse tarafından duyulmadığını', 'Olayın gürültülü bir ortamda geçtiğini'], 'Örneğin "Bayram eli kulağında" denildiğinde bayramın çok yaklaştığı anlatılır.'),
  ('Verilen öğütleri hiç dikkate almayan biri için hangi deyim kullanılır?', 'Kulak asmamak', ['Kulağına küpe olup ders almak', 'Kulak kabartıp dikkatle dinlemek', 'Kulak misafiri olup kulak vermek'], 'Kulak asmamak, söyleneni önemsememek ve dinlememek anlamına gelir. "Kulak kabartmak" ise dikkatle dinlemeye çalışmaktır.'),
  ('Bir arkadaşının sırrını başkalarına anlattığı ortaya çıkan ve bu yüzden güvenini yitiren kişi için hangi deyim kullanılır?', 'Gözden düşmek', ['Göz boyamak ve aldatmak', 'Gözü kara olup korkusuzca davranmak', 'Göz kulak olup bakım sağlamak'], 'Gözden düşmek, eskiden sevilen ya da güvenilen birinin bu değerini yitirmesidir.'),
  ('"Gözü kara" deyimi nasıl bir kişiyi anlatır?', 'Hiçbir tehlikeden çekinmeyen, korkusuz kişiyi', ['Gözleri koyu renkli olan, sakin bakışlı kişiyi', 'Kötü niyetli ve kıskanç bakışları olan kişiyi', 'Gece karanlıkta iyi göremeyen kişiyi'], 'Gözü kara kişi, sonuçlarını düşünmeden tehlikeye atılan cesur biridir.'),
  ('Bir arkadaşının küçük bir yardımına çok sevinen birinin "Sana bir fincan kahvenin kırk yıl hatırı var." demesi neyi gösterir?', 'İyiliği unutmayacağını', ['Kahve içmeye davet ettiğini', 'Arkadaşından borç istediğini', 'Kırk yıldır tanıştıklarını'], 'Bu söz, küçük bir iyiliğin bile uzun süre hatırlanacağını, vefa duyulacağını anlatır.'),
  ('"Ayvayı yemek" deyimi hangi durumu anlatır?', 'Kötü bir duruma düşmek', ['Çok iyi beslenmek', 'Bahçede meyve toplayıp kış için saklamak', 'Bir yarışmayı kazanmak'], 'Deyim, birinin içinden çıkılması zor bir sıkıntıya ya da başarısızlığa uğramasını anlatır.'),
  ('"El elden üstündür." atasözü hangi gerçeği hatırlatır?', 'Her zaman daha usta biri bulunabilir.', ['Herkes eşit derecede yeteneklidir ve kimse kimseden üstün değildir.', 'Elle yapılan işler makinelerden daha değerlidir.', 'Yardımlaşan insanlar her işi başarır.'], 'Atasözü, kişinin kendini en iyi saymaması gerektiğini, her ustadan daha usta birinin çıkabileceğini anlatır.'),
  ('Bir mahallede yaşayan herkesin birbirine destek olması sayesinde sorunların kolayca çözüldüğü görülüyor. Bu durum hangi atasözüyle anlatılır?', 'Nerde birlik, orda dirlik.', ['Her kuşun eti yenmez, herkes kolay lokma değildir.', 'Gülme komşuna gelir başına, dikkatli ol.', 'Kel başa şimşir tarak, gereksiz lükstür.'], 'Birlik ve dayanışma olan yerde huzur ve düzen de olur.'),
  ('Bayram ziyaretinde konuklara geleneksel olarak ilk ne ikram edilir?', 'Kolonya ve şeker', ['Ayran ve pide', 'Çorba ve ekmek', 'Meyve suyu ve kek'], 'Bayramda konuklar kapıdan girince ellerine kolonya dökülür, ardından şeker ya da lokum ikram edilir; sonra kahve ve tatlı gelir.'),
  ('Eve giren konuğun ayakkabılarını kapı girişinde çıkarması geleneği en çok hangi amaca hizmet eder?', 'Evin temizliğini korumak', ['Konuğun ayaklarını dinlendirmek', 'Ayakkabının çalınmasını önlemek', 'Ev sahibine yeni terlik aldırmak'], 'Türk evlerinde yerde oturma ve yer sofrası geleneği vardır; sokağın kiri içeri taşınmasın diye ayakkabı kapıda çıkarılır.'),
  ('Bir konuk gelip "Hoş geldiniz." diye karşılandığında verdiği geleneksel yanıt hangisidir?', 'Hoş bulduk.', ['Güle güle.', 'Sağ olun, ben gideyim.', 'Size de afiyet olsun.'], 'Karşılıklı bu kalıp sözler Türkçenin nezaket geleneğinin bir parçasıdır.'),
  ('Yeni bir eve taşınan komşuya geleneksel olarak ne götürülür?', 'Bir tabak yiyecek ya da tatlı', ['Eski mobilyalar', 'Bir çuval kömür', 'Boş bir sandık'], 'Yeni gelen komşuya yemek ya da tatlı götürmek, onu mahalleye kabul etmenin ve dostluk kurmanın ilk adımıdır. Tabak da boş geri verilmez.'),
  ('Komşudan gelen yemek tabağının geri verilirken boş gönderilmemesi geleneği neyi gösterir?', 'İkrama ikramla karşılık verme inceliğini', ['Tabakların sayısının azalmasından korkulduğunu', 'Yemeğin beğenilmediğini', 'Komşunun borç istediğini'], 'Tabağa bir yiyecek koyarak geri vermek, gösterilen ilgiye teşekkürün ve komşuluk ilişkisinin sürdüğünün işaretidir.'),
  ('Kına gecesinde gelinin avucuna kına yakıldıktan sonra eline neden bez ya da eldiven geçirilir?', 'Kınanın tutup rengini iyi vermesi için', ['Gelinin ellerinin üşümemesi için', 'Gelinin yüzüğünü gizlemek için', 'Konukların kınayı görmemesi için'], 'Kına bir süre beklemelidir. Elin sarılması kınanın dökülmeden tutmasını ve koyu renk vermesini sağlar.'),
  ('Doğan bebek için hazırlanan, sallandıkça bebeği uyutan geleneksel ahşap yatağa ne ad verilir?', 'Beşik', ['Sedir ya da divan', 'Divan', 'Hamak'], 'Beşik çoğu zaman ahşaptan yapılır ve oymalarla süslenir. Bebeği beşiğe yatırırken ninni söylenir.'),
  ('Türkiye\'de çayın geleneksel olarak demlendiği, üst üste konan iki kaptan oluşan düzenek hangisidir?', 'Çaydanlık ve demlik', ['Cezve ve fincan', 'Semaver ve tek kulplu kepçe', 'Güğüm ve ibrik'], 'Alttaki çaydanlıkta su kaynar, üstteki demlikte çay buharla demlenir. Bardağa önce demlikteki koyu çay, sonra sıcak su konur.'),
  ('Türk çay kültüründe çayın sunulduğu geleneksel bardak hangi biçimiyle tanınır?', 'İnce belli', ['Kulplu ve kalın', 'Geniş ağızlı ve kısa', 'Kapaklı ve uzun'], 'İnce belli bardak çayın rengini gösterir ve dudakların yanmadan tutulmasını kolaylaştırır.'),
  ('Bir kişi çay ikram edilirken "açık olsun" diyorsa ne istemektedir?', 'Bardakta daha az demli çay, daha çok su olmasını', ['Bardağın ağzına kadar doldurulmasını', 'Çayın şekersiz verilmesini', 'Çayın limonla servis edilmesini'], 'Açık çay az demlidir ve rengi açık kızıldır; koyu ya da "tavşan kanı" çay ise daha çok dem içerir.'),
  ('Türkiye\'de çay tarımının yoğun olarak yapıldığı ve çayla özdeşleşen il hangisidir?', 'Rize', ['Hatay', 'Kırşehir', 'Edirne'], 'Rize, iklimi sayesinde Türkiye\'nin başlıca çay üretim bölgesidir. Çay kültürü 2022\'de Azerbaycan ile ortak başvuruyla UNESCO listesine girmiştir.'),
  ('Anadolu\'da sazdan, kamıştan ya da saplardan örülerek yapılan taşıma ve saklama kaplarına genel olarak ne ad verilir?', 'Sepet', ['Testi ya da küp', 'Küp', 'Güğüm'], 'Sepet örücülüğü söğüt, kamış, hasır otu gibi bitkilerle yapılan eski bir el sanatıdır.'),
  ('Kumaş üzerine renkli ipliklerle desen işlemek anlamına gelen el sanatı hangisidir?', 'Nakış', ['Ebru', 'Tezhip', 'Hat'], 'Nakış, iğne ve iplikle kumaşa motif işlemektir. Anadolu\'da çeyiz eşyalarının büyük kısmı nakışla süslenir.'),
  ('Oltu taşı, kehribar ya da sedef gibi malzemelerden dizilerek yapılan, elde çekilen boncuk dizisine ne ad verilir?', 'Tespih', ['Gerdanlık', 'Halhal', 'Bilezik'], 'Tespih genellikle 33 ya da 99 tanelidir. Tespih yapımı Erzurum ve Oltu\'da önemli bir el sanatı olarak sürer.'),
  ('Kurban Bayramı\'nda kesilen kurbanın etinin geleneksel olarak paylaşımı nasıl yapılır?', 'Üçe bölünüp aile, akraba-komşu ve yoksullar arasında paylaştırılır.', ['Tamamı kurbanı kesen aile tarafından tüketilir.', 'Tamamı pazarda satılıp parası bağışlanır.', 'Yalnızca konuklara yemek olarak ikram edilir.'], 'Geleneğe göre kurban eti üç pay edilir: bir payı ev halkına, bir payı akraba ve komşulara, bir payı da yoksullara ayrılır.'),
  ('Bayramdan bir gün önceki, hazırlıkların yapıldığı ve mezarların ziyaret edildiği güne ne ad verilir?', 'Arife', ['Kandil', 'Sahur', 'Bayram ertesi'], 'Arife günü evler temizlenir, tatlılar hazırlanır ve birçok yerde mezarlıklar ziyaret edilir.'),
  ('Bayramda kapı kapı dolaşan çocuklara verilen şeker ya da paranın gelenekteki işlevi hangisidir?', 'Bayram sevincinin çocuklarla paylaşılması', ['Çocukların okul masraflarının karşılanması', 'Mahalle bekçisine verilen ücretin dağıtılması', 'Çocukların komşulara yaptığı işin karşılığı'], 'Çocuklara verilen şeker ve harçlık, bayramın onlar için de bir şenlik olmasını ve kuşaklar arası sevginin sürmesini sağlar.'),
  ('Bağlama çalarken tellere vurmak için kullanılan küçük ve esnek parçaya ne ad verilir?', 'Mızrap ya da tezene', ['Kulak ya da burgu denen parça', 'Eşik ya da köprü', 'Tekne ya da gövde'], 'Mızrap eskiden kiraz ağacı kabuğundan ya da boynuzdan yapılırdı, bugün çoğunlukla plastiktir.'),
  ('Çobanların yalnız kaldıkları dağlarda çaldığı, tahtadan ya da kamıştan yapılan uzun düdüğe ne ad verilir?', 'Kaval', ['Zurna ya da klarnet', 'Ney', 'Mey'], 'Kaval, ağaçtan yapılan, dudakla yandan üflenen yumuşak sesli bir çalgıdır. Halk anlatılarında çobanla özdeşleşir.'),
  ('Davul ve zurnaya yönelik "Davul zurna ile ilan etmek" sözü bugün hangi anlamda kullanılır?', 'Bir şeyi herkese gösterişli biçimde duyurmak', ['Bir şeyi gizlice ve sessizce yapmak', 'Bir düğünü tümüyle iptal etmek', 'Bir müzik dersine başlamak'], 'Davul ve zurna eskiden haber ve duyuruların da aracıydı. Deyim, bir şeyi geniş kitlelere yüksek sesle yaymayı anlatır.'),
  ('Sürekli tatilden söz eden bir arkadaşı için "Dervişin fikri ne ise zikri de odur." diyen biri neyi kastetmektedir?', 'Onun aklının tatilde olduğunu', ['Onun çok bilgili olduğunu ve öğrettiğini', 'Onun dindar bir kişi olduğunu ve ibadet ettiğini', 'Onun tatilden nefret ettiğini ve kaçtığını'], 'Söz, bir kimsenin hep aynı şeyden söz etmesinin, o konuyu sürekli düşündüğünü gösterdiğini anlatır.'),
  ('"Hamama giren terler." atasözü hangi durumu anlatır?', 'Bir işe giren, o işin zahmetine de katlanır.', ['Hamamlar yalnızca kışın kullanılmalıdır ve sıcaktır.', 'Sağlıklı olmak için her hafta hamama gitmek gerekir.', 'Terleyen insanlar çabuk hastalanır ve üşür.'], 'Hamama giren kişinin terlemesi kaçınılmazdır; bir işe girişen de onun getirdiği zorluk ve sonuçlara katlanmalıdır.'),
  ('"Armut dibine düşer." atasözü hangi durum için söylenir?', 'Çocuğun anne ya da babasına benzemesi', ['Meyvelerin olgunlaşınca kendiliğinden düşmesi ve toplanması', 'Bahçedeki ağaçların budanması gereken zaman', 'Hasat mevsiminin yaz sonunda başlaması ve bitmesi'], 'Armudun kendi ağacının dibine düşmesi gibi çocuklar da huy ve davranışlarıyla ailesine benzer.'),
  ('Hıdırellez günü kırlara çıkılıp yeşillik üzerinde yemek yenmesi geleneğinin baharla ilgili anlamı nedir?', 'Doğanın uyanışını kutlamak ve bereket dilemek', ['Kışlık yiyeceklerin bitmesi', 'Evlerin temizlik için boşaltılması', 'Hayvanların yaylaya götürülmesi'], 'Hıdırellez doğanın yeniden canlandığı zamandır. Kırlara çıkmak, yeşillikle temas edip sağlık ve bereket dilemek anlamına gelir.'),
  ('Taziyeye gelenlerin yas evinde "Başınız sağ olsun." demesine verilen geleneksel yanıt hangisidir?', 'Dostlar sağ olsun.', ['Afiyet olsun.', 'Güle güle kullanın.', 'Hayırlı olsun.'], 'Bu karşılıklı sözler yas tutanı teselli etmeye ve gösterilen ilgiye teşekküre dayanır.'),
  ('Yeni bir işe başlayan ya da dükkân açan birine geleneksel olarak ne denir?', 'Hayırlı olsun.', ['Geçmiş olsun ve acil şifalar.', 'Başınız sağ olsun ve sabırlar.', 'Allah rahmet eylesin.'], '"Hayırlı olsun" yeni başlangıçların iyilikle ve kazançla sürmesi dileğidir.'),
  ('Bir hastayı ziyaret eden kişinin söylediği geleneksel dilek hangisidir?', 'Geçmiş olsun.', ['Hayırlı olsun ve bol kazançlar.', 'Güle güle oturun.', 'Bayramınız kutlu olsun.'], '"Geçmiş olsun" hastalığın ya da sıkıntının çabuk geçmesi dileğidir.'),
  ('Yeni ev alan birini ziyarete giderken söylenen geleneksel dilek hangisidir?', 'Güle güle oturun.', ['Geçmiş olsun ve acil şifalar.', 'Dostlar sağ olsun.', 'Başınız sağ olsun.'], '"Güle güle oturun" yeni evde mutlulukla yaşanması dileğidir.'),
  ('Bir kişinin yeni giysisi için ona söylenen geleneksel dilek hangisidir?', 'Güle güle giy.', ['Kolay gelsin ve iyi çalışmalar.', 'Hayırlı yolculuklar.', 'Ellerine sağlık, afiyet olsun.'], '"Güle güle giy" ya da "güle güle kullan" yeni alınan eşyanın mutlulukla kullanılması dileğidir.'),
];
